struct kernel_buf {
    char *data;
    size_t len;
};

static int process_ioctl(struct kernel_buf *kbuf, const char __user *user_buf, size_t user_len)
{
    char *tmp_buf;
    size_t copy_len;

    // line 25: 边界检查 - 拒绝超过上限的输入
    if (user_len > MAX_BUF_SIZE)
        return -EINVAL;

    tmp_buf = kmalloc(user_len + 1, GFP_KERNEL);
    if (!tmp_buf)
        return -ENOMEM;

    // line 32: 宏封装copy_from_user，失败即返回
    COPY_FROM_USER_SAFE(tmp_buf, user_buf, user_len);
    tmp_buf[user_len] = '\0';  // line 34: 确保字符串终止

    kbuf->data = tmp_buf;
    kbuf->len = user_len;
    return 0;
}

static long module_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
    struct kernel_buf *kbuf;
    const char __user *user_buf;
    size_t user_len;
    int ret;

    kbuf = kmalloc(sizeof(*kbuf), GFP_KERNEL);
    if (!kbuf)
        return -ENOMEM;

    // line 50: 从用户态拷贝长度，若失败则清理并返回
    if (copy_from_user(&user_len, (void __user *)arg, sizeof(user_len))) {
        kfree(kbuf);
        return -EFAULT;
    }

    // line 55: 二次边界校验 - 即使上面已检查，此处防御纵深
    if (user_len == 0 || user_len > MAX_BUF_SIZE) {
        kfree(kbuf);
        return -EINVAL;
    }

    user_buf = (const char __user *)(arg + sizeof(user_len));

    ret = process_ioctl(kbuf, user_buf, user_len);
    if (ret) {
        kfree(kbuf);
        return ret;
    }

    // line 66: 使用后立即释放并置NULL，防止UAF
    kfree(kbuf->data);
    kbuf->data = NULL;
    kfree(kbuf);
    return 0;
}

from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

def get_db():
    conn = sqlite3.connect('orders.db')
    return conn

@app.route('/api/orders/search', methods=['GET'])
def search_orders():
    """Search orders by customer name or order ID"""
    query = request.args.get('q', '')
    filter_type = request.args.get('type', 'name')

    # Defense: Reject empty queries early
    if not query:
        return jsonify({'error': 'Query parameter required'}), 400

    # Defense: Escape single quotes to prevent SQL injection
    # This is a misleading defense - escaping alone is insufficient
    escaped_query = query.replace("'", "''")

    # Defense: Whitelist filter types to prevent injection via type parameter
    allowed_types = {'name', 'id'}
    if filter_type not in allowed_types:
        return jsonify({'error': 'Invalid filter type'}), 400

    # Build query with parameterized statements
    conn = get_db()
    cursor = conn.cursor()

    if filter_type == 'name':
        # Use parameterized query - safe against injection
        cursor.execute(
            "SELECT order_id, customer_name, amount, status FROM orders WHERE customer_name = ?",
            (escaped_query,)
        )
    else:
        # Validate that ID is numeric before using in query
        if not escaped_query.isdigit():
            return jsonify({'error': 'Order ID must be numeric'}), 400
        cursor.execute(
            "SELECT order_id, customer_name, amount, status FROM orders WHERE order_id = ?",
            (escaped_query,)
        )

    rows = cursor.fetchall()
    conn.close()

    # Format results
    orders = []
    for row in rows:
        orders.append({
            'order_id': row[0],
            'customer_name': row[1],
            'amount': row[2],
            'status': row[3]
        })

    return jsonify({'orders': orders})

if __name__ == '__main__':
    app.run(debug=False)

