// backupConfig 定时备份任务配置
type backupConfig struct {
	TargetDir string // 备份目标目录
	DBName    string // 数据库名称
}

// runBackup 执行数据库备份
func runBackup(cfg backupConfig) error {
	// 白名单校验：仅允许字母数字和下划线，防止命令注入
	if !isValidIdentifier(cfg.DBName) {
		return fmt.Errorf("invalid db name: %s", cfg.DBName)
	}
	if !isValidIdentifier(cfg.TargetDir) {
		return fmt.Errorf("invalid target dir: %s", cfg.TargetDir)
	}

	// 使用 subprocess 列表参数 + shell=False，避免 shell 解释
	cmd := exec.Command("pg_dump", "-U", "postgres", "-f", cfg.TargetDir+"/backup.sql", cfg.DBName)
	cmd.Dir = "/var/backups" // 限制工作目录
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("backup failed: %v, output: %s", err, string(output))
	}
	return nil
}

// isValidIdentifier 白名单校验：仅允许安全字符
func isValidIdentifier(s string) bool {
	if len(s) == 0 || len(s) > 64 {
		return false
	}
	for _, r := range s {
		if !(r >= 'a' && r <= 'z') && !(r >= 'A' && r <= 'Z') && !(r >= '0' && r <= '9') && r != '_' {
			return false
		}
	}
	return true
}

// scheduleBackup 定时调度备份任务
func scheduleBackup() {
	ticker := time.NewTicker(24 * time.Hour)
	defer ticker.Stop()

	for range ticker.C {
		cfg := backupConfig{
			TargetDir: "/data/backup_" + time.Now().Format("20060102"),
			DBName:    "products_db",
		}
		if err := runBackup(cfg); err != nil {
			fmt.Printf("scheduled backup error: %v\n", err)
		} else {
			fmt.Println("scheduled backup completed")
		}
	}
}

func main() {
	// 实际运行中由 cron 或类似机制调用
	// scheduleBackup()
	_ = scheduleBackup
}

