const { execFile } = require('child_process');
const path = require('path');

// 白名单允许的构建工具
const ALLOWED_COMMANDS = new Set(['build', 'test', 'package']);

// 安全执行构建命令，使用 execFile 避免 shell 解释
async function runBuildCommand(command, projectPath) {
  // 第 1 层防御：命令白名单校验
  if (!ALLOWED_COMMANDS.has(command)) {
    throw new Error(`Command '${command}' not allowed`);
  }

  // 第 2 层防御：路径规范化并限制在容器工作目录内
  const normalizedPath = path.resolve(projectPath);
  const workspaceRoot = path.resolve('/workspace');
  if (!normalizedPath.startsWith(workspaceRoot)) {
    throw new Error('Invalid project path');
  }

  // 第 3 层防御：使用 execFile 直接传递参数数组，不经过 shell
  return new Promise((resolve, reject) => {
    execFile(
      '/usr/local/bin/container-runner',
      [command, '--project-dir', normalizedPath],
      { timeout: 30000, env: { ...process.env, NODE_ENV: 'production' } },
      (error, stdout, stderr) => {
        if (error) {
          reject(new Error(`Build failed: ${stderr}`));
          return;
        }
        resolve(stdout);
      }
    );
  });
}

// 容器入口
async function containerEntryPoint() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.error('Usage: container-entry <command> <project-path>');
    process.exit(1);
  }

  const [command, projectPath] = args;

  try {
    const output = await runBuildCommand(command, projectPath);
    console.log('Build output:', output);
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
}

containerEntryPoint();
